params.script_inline:
import sys, json, uuid

d = json.load(sys.stdin)["body"]
msgs = d.get("messages", [])
user_turn = None
for m in msgs:
    if m.get("origin") == "user" and m.get("type") == "text":
        user_turn = m
        break
if user_turn is None:
    # Echo guard: store replies / non-user input end here (terminal empty multi-send).
    sys.stdout.write(json.dumps([]))
    sys.exit(0)

question = user_turn.get("text", "")
turn_id = str(uuid.uuid4())

TOOLS = {
    "web_search": {"description": "Search the web.", "parameters": {"type": "object", "properties": {"query": {"type": "string"}}, "required": ["query"]}},
    "web_fetch": {"description": "Fetch one URL (GET).", "parameters": {"type": "object", "properties": {"url": {"type": "string"}}, "required": ["url"]}},
    "remember": {"description": "Persist a note into the answers store.", "parameters": {"type": "object", "properties": {"operation": {"type": "string", "enum": ["insert"]}, "table": {"type": "string", "enum": ["answers"]}, "row": {"type": "object"}}, "required": ["operation", "table", "row"]}}
}

ins = {"operation": "insert", "table": "thread",
       "row": {"turn_id": turn_id, "iter": 0, "role": "user", "turn": json.dumps(user_turn)}}
out = [
    {"header": {"route": "ustore"},
     "messages": [{"origin": "assistant", "type": "tool_call", "id": "u-ins", "text": json.dumps(ins)}]},
    {"header": {"route": "ullm", "question": question, "turn_id": turn_id},
     "system": {
        "identity": {"soul": {"text": "You are a research assistant. Gather facts by calling tools; you may issue several tool calls in one turn. When the tool results answer the user's question, reply with the final answer in German: state each fact and cite its source URL from the tool results as [source: <url>]. Do not invent data; if material is missing for a part of the question, say so explicitly."}},
        "tools": {name: {"text": json.dumps({"type": "function", "function": {"name": name, **schema}})} for name, schema in TOOLS.items()}
     },
     "messages": [user_turn]}
]
sys.stdout.write(json.dumps(out))
